function UIBattlingTipsOnSkillShowPanel:__init()
    self.eventShowSkillStart = nil --- 技能展示开始事件
    self.eventShowSkillEnd = nil --- 技能展示结束事件
    self.eventShowSkillFailed = nil -- 技能释放失败
    self.eventSkillCardChange = nil -- 技能卡改变（升星降星）
