function UIBattlingTipsOnSkillShowPanel:Awake()
    self:FillSkillCardSequeneLB()
    local playMode = UIBattlingCtrlMgr:GetInstance().playMode
    if playMode ~= Constants.PlayMode.Replay then
        self.eventShowSkillStart = Events.AddListener(Constants.EventNames.BattleSkillStartShow, Bind(self, self.OnSkillShow))
        self.eventOnCharacterDead = Events.AddListener(Constants.EventNames.UIBattlingUpdateCharacterAliveState, Bind(self, self.OnCharacterDead))
        self.eventShowSkillFailed = Events.AddListener(Constants.EventNames.BattleSkillFailedShow, Bind(self, self.OnSkillFailed))
        self.eventSkillCardChange = Events.AddListener(Constants.EventNames.BattleSkillQueueChangeShow, Bind(self, self.OnSkillCardChange))
    end
    self.isFinishCurrent = false
end

function UIBattlingTipsOnSkillShowPanel:OnDestroy()
    if self.coHidePanel then
        cs_coroutine.stop(self.coHidePanel)
    end
    if self.textFitterCo then
        cs_coroutine.stop(self.textFitterCo)
    end
    if self.eventShowSkillStart then
        Events.RemoveListener(Constants.EventNames.BattleSkillStartShow, self.eventShowSkillStart)
    end
    if self.eventOnCharacterDead then
        Events.RemoveListener(Constants.EventNames.UIBattlingUpdateCharacterAliveState, self.eventOnCharacterDead)
    end
    if self.eventShowSkillFailed then
        Events.RemoveListener(Constants.EventNames.BattleSkillFailedShow, self.eventShowSkillFailed)
    end
    if self.eventSkillCardChange then
        Events.RemoveListener(Constants.EventNames.BattleSkillQueueChangeShow, self.eventSkillCardChange)
    end
    self.controller = nil
    self:Delete()
    self = nil
end

