---ResetPanelCurData
--- 重置 面板数据
function UIBattlingTipsOnSkillShowPanel:ResetPanelCurData()
    self.intShowSkillCount = 0
    self.indexSkillShow = 1
    self.skipShowIndexArray = {}
    self.isFinishCurrent = false
    --self.indexSkillShowEnd = 1
    self.SkillCardRoot.transform.anchoredPosition = Vector2.zero
    for i, card in ipairs(self.showSequenceList) do
        local curSkillCard = card.Env
        -- 复原卡牌上显示的死亡状态
        curSkillCard:ResetDeadState()
        curSkillCard:PlayAnimationDefault()
        curSkillCard:PlayAnimationNormal()
        -- 复原显示层级
        local canvas = curSkillCard.controller.gameObject:GetComponent(typeof(Canvas))
        canvas.overrideSorting = true
        canvas.sortingOrder = i
    end
    self:CleanPanelInfo()
end

---OnSkillShow
---@param data table @ {roleId = 1, skillId = 1, skillIndex = 1, star = 1, lv = 1, targetIds = {1,2,3}}
function UIBattlingTipsOnSkillShowPanel:OnSkillShow(data)
    xTry(function()
        if self.isFinishCurrent then return end
        if not UIBattlingDataMgr:CheckIdInCampTeam(BattleInfo.myCamp, data.roleId) then return end
        if not data.isInput then return end

        --- 判断是角色否是玩家队伍
        local roleData = BattleViewMgr:FindRoleView(data.roleId)
        if roleData and not (roleData.isPlayer) and not (roleData.isSkillCat) then return end   -- 剔除玩家角色和猫球（可能就剩下召唤物了）
        local lbSkillCard = self.showSequenceList[self.indexSkillShow]
        if IsNull(lbSkillCard) then return end
        local curSkillCard = lbSkillCard.Env
        if data.roleId ~= curSkillCard.skillCardData.roleId then return end
        -- curSkillCard.controller.transform:SetAsLastSibling() --保证显示层级
        local canvas = curSkillCard.controller.gameObject:GetComponent(typeof(Canvas))
        if not isNull(canvas) then
            local originOrder = canvas.sortingOrder
            canvas.sortingOrder = 7     --保证显示层级
        end
        curSkillCard:PlayAnimationShow()
        
        for i, card in ipairs(self.showSequenceList) do
            KTool.SetActive(card.gameObject, i >= self.indexSkillShow and i <= self.intShowSkillCount)
        end
        self:SetPanelInfo(curSkillCard)

        if self.indexSkillShow > 1 then
            local lb_card = self.showSequenceList[self.indexSkillShow - 1]
            KTool.SetActive(lb_card.gameObject, true)
            lb_card.Env:PlayAnimationEnd()
        end
        
        if self.indexSkillShow >= self.intShowSkillCount then
            self.isFinishCurrent = true
            if IsNull(self.coHidePanel) then
                self.coHidePanel = cs_coroutine.start(function()
                    cs_coroutine.yield_return(CS.UnityEngine.WaitForSecondsRealtime(2))
                    self:SetPanelShow(0)
                    self.coHidePanel = nil
                end)
            end
        end
        
        self.indexSkillShow = self:FindNextShowIndex()  -- 增加index
    end)
end

--- 角色死亡时
---@param roleId number
function UIBattlingTipsOnSkillShowPanel:OnCharacterDead(roleId)
    local roleView = UIBattlingTools.GetRoleViewData(roleId)
    if roleView then
        local roleCampType = roleView.camp
        local isDead = roleView:IsDead()
        if BattleInfo:IsUserCamp(roleCampType) and isDead then
            for i, card in ipairs(self.showSequenceList) do
                local curSkillCard = card.Env
                if roleId == curSkillCard.skillCardData.roleId then
                    table.insert(self.skipShowIndexArray, i)
                    -- 设置成死亡状态
                    curSkillCard:SetDeadState()
                    -- 如果下一个正要展示的角色死掉了，那要手动跳一下index
                    if i == self.indexSkillShow then
                        self.indexSkillShow = self:FindNextShowIndex()
                    end
                end
            end
        end
    end
end

--- 当技能释放失败时
---@param failedInfo table 失败信息 (roleId = 1, skillCardId = 1, star = 1, isInput = true)
function UIBattlingTipsOnSkillShowPanel:OnSkillFailed(data)
    if isNull(data) then return end
    if not data.isInput then return end
    if self.isFinishCurrent then return end

    if not UIBattlingDataMgr:CheckIdInCampTeam(BattleInfo.myCamp, data.roleId) then return end
    local roleData = BattleViewMgr:FindRoleView(data.roleId)
    if roleData and not (roleData.isPlayer) then return end
    local lbSkillCard = self.showSequenceList[self.indexSkillShow]
    if IsNull(lbSkillCard) then return end
    local curSkillCard = lbSkillCard.Env
    if data.roleId ~= curSkillCard.skillCardData.roleId then return end

    for i, card in ipairs(self.showSequenceList) do
        KTool.SetActive(card.gameObject, i >= self.indexSkillShow and i <= self.intShowSkillCount)
    end
    curSkillCard:PlayAnimationDestroy()
    self:CleanPanelInfo()

    if self.indexSkillShow >= self.intShowSkillCount then
        self.isFinishCurrent = true
        if IsNull(self.coHidePanel) then
            self.coHidePanel = cs_coroutine.start(function()
                cs_coroutine.yield_return(CS.UnityEngine.WaitForSecondsRealtime(2))
                self:SetPanelShow(0)
                self.coHidePanel = nil
            end)
        end
    end
    
    self.indexSkillShow = self:FindNextShowIndex()  -- 增加index
end

--- 技能卡改变（升星降星）
---@param data table 卡数据 {index = 1(技能序号), skillIndex = 1, targetId = 1, roleId = 1, star = 1}
function UIBattlingTipsOnSkillShowPanel:OnSkillCardChange(data)
    for i, card in ipairs(self.showSequenceList) do
        local curSkillCard = card.Env
        if data.skillIndex == curSkillCard.skillCardData.skillIndex then
            local cardData = {
                roleId = data.roleId,
                skillId = curSkillCard.skillCardData.skillId,
                star = data.star,
                skillLv = 1,
                skillIndex = data.skillIndex,
            }
            if UIBattlingTools.IsOnlyStarChanged(curSkillCard.skillCardData, cardData) then
                curSkillCard:ChangeCardStar(curSkillCard.skillCardData.star, data.star, cardData)
            end
        end
    end
end

--- 找到下一个可以展示的索引
function UIBattlingTipsOnSkillShowPanel:FindNextShowIndex()
    local index = self.indexSkillShow + 1
    while table.isContain(self.skipShowIndexArray, index) do
        index = index + 1
    end
    return index
end

function UIBattlingTipsOnSkillShowPanel:GetDataWithOutLock(data)
    local result = {}
    for i = 1, #data do
        local seqData = data[i]
        local isLock = seqData.isLock
        if not isLock then
            table.insert(result, seqData.data)
        end
    end
    return result
end


---InitShowData
---初始化 展示信息
---@param dataList table
function UIBattlingTipsOnSkillShowPanel:InitShowData(dataList)
    self:ResetPanelCurData()
    local dataWithOutLock = self:GetDataWithOutLock(dataList)
    self.intShowSkillCount = #dataWithOutLock --- 设置当前回合展示的技能卡数量
    for i = 1, #self.showSequenceList do
        if i <= #dataWithOutLock then
            KTool.SetActive(self.showSequenceList[i], true)
            self.showSequenceList[i].Env:ShowSequeneSkillCardOnSkillShow(dataWithOutLock[i])
        else
            KTool.SetActive(self.showSequenceList[i], false)
        end
        self.showSequenceList[i].gameObject.transform.localScale = Vector3.one * SkillCardScaleDefault
    end
end

---SetPanelShow
---设置 Panel 显示状态
---@param type number  1:显示 2: 隐藏
function UIBattlingTipsOnSkillShowPanel:SetPanelShow(type, noAnim)
    if type == 1 and self.intShowSkillCount == 0 then return end    -- 如果没有要说明的技能，那么就不显示
    if noAnim then
        self.PanelCanvasGroup.alpha = type == 1 and 1 or 0
    else
        self.PanelCanvasGroup:DOFade(type == 1 and 1 or 0, 0.35):SetEase(DOTween.Ease.InOutQuad)
        if type == 1 then
            self.Animation_AnimRoot:Play("TipsOnSkillShow_Enter")
        end
    end
end

---FillSkillCardSequeneLB
---填充 技能卡 LB
function UIBattlingTipsOnSkillShowPanel:FillSkillCardSequeneLB()
    local skillCardLBCount = 6      -- 写死6个，动画也k了6了。（目前设计上，最多会有6个人）
    for i = 1, skillCardLBCount do
        local normalSkillCard = KTool.Instantiate(self.NormalSkillCardRoot.gameObject, self.NormalSkillCardInstance.gameObject)
        -- 这里重命名了一下，因为和动画约定了6个go名字
        normalSkillCard.name = "Card_" .. tostring(i)
        -- 这里修改了canvas的层级，让上面的卡牌显示在下面
        local canvas = normalSkillCard:GetComponent(typeof(Canvas))
        canvas.sortingOrder = i
        KTool.SetActive(normalSkillCard, true)
        table.insert(self.showSequenceList, normalSkillCard:GetComponent(typeof(LuaBehaviour)))
    end
end

---SetPanelInfo
---@param data table @ {roleId = 1, skillId = 1, skillIndex = 1, star = 1, lv = 1, targetIds = {1,2,3}}
function UIBattlingTipsOnSkillShowPanel:SetPanelInfo(data)
    xTry(function()
        local skillCardId = data.skillCardData.skillId
        local skillCardVO = UIBattlingTools.GetSkillCardInfoByTwoParam(skillCardId)
        self.Text_SkillName.text = skillCardVO.skillName -- 技能名
        --- 技能 Tags 列表
        self:CleanTagCells()
        ---@type CardProgressionSkillUtils
        local CardProgressionSkillUtils     = import("Game.CardProgression.CardProgressionSkillUtils")
        local skillTags = CardProgressionSkillUtils.GetSkillTags(skillCardVO.abstractLabel, data.skillCardData.star)
        KTool.SetActive(self.SkillTagList.gameObject, skillTags and #skillTags > 0)
        local limitValueShow = 4
        for i, labelId in ipairs(skillTags) do
            if i <= limitValueShow then
                local descTag = CfUtils.GetCfData(AutoIds.IdSetting284, labelId, "desc", Constants.DataType.LocalString)
                local goCell = self:InitTagCell()
                self:SetTagCellInfo(goCell, descTag)
            end
        end
        --- 设置技能描述
        local roleView = BattleViewMgr:FindRoleView(data.skillCardData.roleId)
        local rare = 1
        if roleView.isSkillCat then
            rare = roleView.rare
        else
            local cardVo = CardConfMgr:GetCardByRefId(roleView.typeId)
            rare = cardVo.rare
        end

        local star = data.skillCardData.star
        local desc = UIBattlingTools.GetSkillDescInBattle(skillCardId, star, rare, true)
        self.TxtSkillDescription.text = desc
        --- 设置伤害类型描述
        local damageDesc = UIBattlingTools.GetSkillDamageTypeDescInBattle(skillCardId, star)
        if string.len(damageDesc) > 0 then
            KTool.SetActive(self.TxtSkillDescription2, true)
            self.TxtSkillDescription2.text = damageDesc
        else
            KTool.SetActive(self.TxtSkillDescription2, false)
        end
        -- 自适应修改描述文本的对齐方式
        self:AutoFitterSkillDescriptions()

        self.Animation_SkillDescNode:Play("SkillDescNode_Enter")
    end)
end

