function UIBattlingTipsOnSkillShowPanel:CleanPanelInfo()
    self.Text_SkillName.text = ""
    self:CleanTagCells()
    self.TxtSkillDescription.text = ""
    self.TxtSkillDescription2.text = ""
end

------------ TagCell ------------
function UIBattlingTipsOnSkillShowPanel:CleanTagCells()
    if isNull(self.tagCells) then return end
    for i = #self.tagCells, 1, -1 do
        KTool.SafeDelete(self.tagCells[i].gameObject)
    end
    self.tagCells = nil
end

function UIBattlingTipsOnSkillShowPanel:InitTagCell()
    if isNull(self.tagCells) then self.tagCells = {} end
    local go = KTool.Instantiate(self.SkillTagList.gameObject, self.SkillTagCell.gameObject)
    KTool.SetActive(go, true)
    table.insert(self.tagCells, go)
    return go
end

function UIBattlingTipsOnSkillShowPanel:SetTagCellInfo(go, desc)
    local txtDesc = go.transform:Find("Text_SkillTag").gameObject:GetComponent(typeof(Text))
    txtDesc.text = desc
end
------------ TagCell ------------

function UIBattlingTipsOnSkillShowPanel:AutoFitterSkillDescriptions()
    self.textFitterCo = cs_coroutine.start(function()
        -- 先等缓存刷新
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))

        local generator1 = self.TxtSkillDescription.cachedTextGenerator
        local lineCount1 = generator1.lines.Count
        local generator2 = self.TxtSkillDescription2.cachedTextGenerator
        local lineCount2 = generator2.lines.Count

        if lineCount1 <= 1 and lineCount2 <= 1 then
            self.TxtSkillDescription.alignment = CS.UnityEngine.TextAnchor.LowerRight
            self.TxtSkillDescription2.alignment = CS.UnityEngine.TextAnchor.LowerRight
        else
            self.TxtSkillDescription.alignment = CS.UnityEngine.TextAnchor.LowerLeft
            self.TxtSkillDescription2.alignment = CS.UnityEngine.TextAnchor.LowerLeft
        end

        self.textFitterCo = nil
    end)
end

return UIBattlingTipsOnSkillShowPanel
